def esc(s):
    s = escape(s).replace("'", "\\'").replace('"', '\\"')
    if s.startswith("@") or s.startswith("?"): s = "\\" + s
    return s

root = os.path.join(os.path.dirname(__file__), "..", "app", "src", "main", "res")
for i, lang in enumerate(L):
    d = os.path.join(root, "values" if lang == "en" else "values-" + lang)
    os.makedirs(d, exist_ok=True)
    out = ['<?xml version="1.0" encoding="utf-8"?>', '<!-- tools/gen_strings.py 로 생성. 직접 고치지 말 것 -->', '<resources>']
    for k, v in S.items():
        fmt = ' formatted="false"' if re.search(r"%\d\$", v[i]) is None and "%" in v[i] else ""
        out.append(f'    <string name="{k}"{fmt}>{esc(v[i])}</string>')
    for k, v in P.items():
        out.append(f'    <plurals name="{k}">')
        for q, t in v[lang].items(): out.append(f'        <item quantity="{q}">{esc(t)}</item>')
        out.append('    </plurals>')
    out.append('</resources>')
    open(os.path.join(d, "strings.xml"), "w", encoding="utf-8").write("\n".join(out) + "\n")
print("ok", len(S), "strings,", len(P), "plurals x", len(L))
